"""Apply an owned contact profile feature to an independent M38 copy."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[3]
BASE=ROOT.parent/'unpack_work/campaign_m38_integrated_candidate/ark_sim'
DEST=ROOT.parent/'unpack_work/campaign_m41_hole_contact_candidate/ark_sim'
def change(name,old,new):
    p=DEST/name;s=p.read_text(encoding='utf-8');assert old in s,(name,old);p.write_text(s.replace(old,new),encoding='utf-8',newline='')
