    change('domains/movement.py','            spatial = self.ctx.get(ref, ("spatial",), {})\n            if spatial.get("forced_motion"):', '            spatial = self.ctx.get(ref, ("spatial",), {})\n            if self.ctx.tile_contacts is not None:\n                self.ctx.tile_contacts.inspect(ref,"movement_check")\n                if not self.ctx.active(ref):continue\n            if spatial.get("forced_motion"):')
    change('domains/movement.py','grid.clip_segment(position, destination, route_motion_mode(spatial.get("route")))','grid.clip_segment(position, destination, route_motion_mode(spatial.get("route")), forced=True)')
    change('domains/movement.py','            motion["remaining_distance"] = max(0, motion["remaining_distance"]-actual)', '            if not self.ctx.active(target):return\n            motion["remaining_distance"] = max(0, motion["remaining_distance"]-actual)')
    change('domains/movement.py','        self.ctx.spatial.blocking()\n\n    def displace', '        self.ctx.spatial.blocking()\n\n    def set_motion_mode(self,source,target,mode):\n        if type(mode) is not int or mode not in (0,1):raise ValueError("motion mode must be WALK0/FLY1")\n        with self.ctx.session.atomic():\n            spatial=self.ctx.get(target,("spatial",),{})\n            spatial["motion_mode"]=mode\n            if spatial.get("route"):\n                spatial["route"]["motionMode"]=mode\n            spatial.pop("movement_path",None);spatial.pop("velocity",None)\n            self.ctx.set(target,("spatial",),spatial)\n            self.ctx.emit("movement.motion_changed",{"source":source,"target":target,"mode":mode})\n            if self.ctx.tile_contacts is not None:self.ctx.tile_contacts.inspect(target,"motion_changed",source)\n            self.ctx.spatial.blocking()\n\n    def displace')
    change('domains/effects.py','            elif operation in ("move", "displace"):', '            elif operation == "set_motion_mode":\n                self.ctx.movement.set_motion_mode(source,target,effect["value"])\n            elif operation in ("move", "displace"):')
    change('domains/effects.py','"area", "push", "move", "displace", "trigger_ability"','"area", "push", "move", "displace", "trigger_ability", "set_motion_mode"')
    change('domains/lifecycle.py','        if route is not None:\n            spatial["route"] = thaw(route)','        if route is not None:\n            spatial["route"] = thaw(route)\n        if "motion_mode" in spatial:\n            if type(spatial["motion_mode"]) is not int or spatial["motion_mode"] not in (0,1):raise ValueError("explicit spatial motion mode WALK0/FLY1 required")\n            if spatial.get("route"):spatial["route"]["motionMode"]=spatial["motion_mode"]')
    change('domains/movement.py','grid.clip_segment(position, destination, route_motion_mode(spatial.get("route")), forced=True)','grid.clip_segment(position, destination, self.ctx.tile_contacts.mode(target) if self.ctx.tile_contacts is not None else route_motion_mode(spatial.get("route")), forced=True)')
    change('content/schemas.py','"buff": {"selection_flags",','"buff": {"contact_flags", "selection_flags",')
    change('content/schemas.py','"spatial": {"coordinate_space",','"spatial": {"motion_mode", "coordinate_space",')
    change('content/schemas.py','        spatial = components.get("spatial", {})','        spatial = components.get("spatial", {})\n        if "motion_mode" in spatial and (type(spatial["motion_mode"]) is not int or spatial["motion_mode"] not in (0,1)):\n            raise ContentError(identifier+": explicit spatial motion mode WALK0/FLY1 required")')
    for label in ('entity','wave'):
        change('content/schemas.py',f'            spatial = {label}.get("components", {{}}).get("spatial", {{}})',f'            spatial = {label}.get("components", {{}}).get("spatial", {{}})\n            if "motion_mode" in spatial and (type(spatial["motion_mode"]) is not int or spatial["motion_mode"] not in (0,1)):\n                raise ContentError(path+": explicit spatial motion mode WALK0/FLY1 required")')
    change('content/schemas.py','"effects": {"damage",','"effects": {"set_motion_mode", "damage",')
    change('content/schemas.py','    if effect["op"] == "retire":','    if effect["op"] == "set_motion_mode" and (type(effect.get("value")) is not int or effect["value"] not in (0,1)):\n        raise ContentError(path+": explicit WALK0/FLY1 motion mode required")\n    if effect["op"] == "retire":')
    change('content/schemas.py','        if "movement_damage" in definition:', '        if "contact_flags" in definition:\n            flags=definition["contact_flags"]\n            if not isinstance(flags,Mapping) or set(flags)!={"defer_fall"} or type(flags["defer_fall"]) is not bool:\n                raise ContentError(identifier+": contact_flags requires explicit defer_fall boolean")\n        if "movement_damage" in definition:')
    change('content/capabilities.py',"        if profile.get('rule'):require('movement.transition',", "        if profile.get('type')=='contact_lifecycle':require('tile.contact',f\"{scenario['id']}.map.tile_mechanics.{key}\",explicit=profile['rule'])\n        elif profile.get('rule'):require('movement.transition',")
    p=DEST/'rules/contracts.json';j=json.loads(p.read_text(encoding='utf-8'))
