    rows=j['contracts'] if 'contracts' in j else j['calculations']
    rows.append({'id':'tile.contact','kind':'calculation','owner':'source','inputs':[{'name':n,'type':t,'required':True} for n,t in [('entity','entity_snapshot'),('tile','value_map'),('cause','value_map'),('motion_mode','integer'),('ready','boolean'),('parameters','value_map')]],'outputType':'boolean','implementations':['expression','graph','provider'],'pureEvaluation':True,'writesStateDirectly':False,'versionsRequired':True,'outputSchema':{'type':'boolean'},'contractVersion':1,'status':'declared','description':'Explicit model contact eligibility; true permits configured environmental lifecycle settlement.'})
    p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
